import java.util.*;

class Solution {
  public List<List<Integer>> getSkyline(int[][] buildings) {
    List<int[]> points = new ArrayList<>();
    for (int[] b : buildings) {
      points.add(new int[] {b[0], -b[2]}); // start: negative height sorts first at the same x
      points.add(new int[] {b[1], b[2]});
    }
    points.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
    TreeMap<Integer, Integer> heights = new TreeMap<>();
    heights.put(0, 1);
    List<List<Integer>> ans = new ArrayList<>();
    int current = 0;
    for (int[] p : points) {
      if (p[1] < 0) heights.merge(-p[1], 1, Integer::sum);
      else if (heights.merge(p[1], -1, Integer::sum) == 0) heights.remove(p[1]);
      int top = heights.lastKey();
      if (top != current) {
        current = top;
        ans.add(Arrays.asList(p[0], top));
      }
    }
    return ans;
  }
}
